const b = await this.helpers.getBinaryDataBuffer(0, 'data');
const eventos=JSON.parse(b.toString('utf8'));
if (!Array.isArray(eventos)) throw new Error('eventos.json deve conter uma lista');
return [{json:{eventos}}];

const b=await this.helpers.getBinaryDataBuffer(0,'data');
const lojas=JSON.parse(b.toString('utf8'));
if(!Array.isArray(lojas)) throw new Error('lojas.json deve conter uma lista');
const eventos=$('Interpretar eventos').first().json.eventos;
return eventos.map(evento=>({json:{evento,lojas}}));

const b=await this.helpers.getBinaryDataBuffer(0,'data');
const controle=JSON.parse(b.toString('utf8'));
if (!controle || !Array.isArray(controle.alertas) || !Array.isArray(controle.logs)) throw new Error('controle_alertas.json inválido');
const item=$('Percorrer eventos').first().json, e=item.evento, loja=item.lojas.find(l=>l.loja_id===e.loja_id);
const agora=new Date().toISOString(), erros=[];
const uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
if(!e || !uuid.test(e.id||'')) erros.push('id inválido');
if(!loja) erros.push('loja desconhecida');
if(loja && !(loja.equipamentos||[]).includes(e.equipamento_id)) erros.push('equipamento não cadastrado');
if(!['porta_aberta','luz_acesa_sem_necessidade','temperatura_alta'].includes(e.tipo)) erros.push('tipo inválido');
if(!Number.isInteger(e.duracao_s)||e.duracao_s<=0) erros.push('duração inválida');
const d=new Date(e.inicio);if(!e.inicio || Number.isNaN(d.getTime())) erros.push('início inválido');
let acao='ignorar', motivo='', chatId=null, mensagem='';
if(erros.length) { acao='invalido';motivo=erros.join('; '); }
else if(e.tipo!=='porta_aberta'||e.duracao_s<=60) {motivo=e.tipo!=='porta_aberta'?'tipo sem regra de alerta':'duração não superior a 60 segundos';}
else {
 const fmt=new Intl.DateTimeFormat('en-GB',{timeZone:loja.fuso_horario||'America/Sao_Paulo',hour:'2-digit',minute:'2-digit',hourCycle:'h23'});
 const t=fmt.format(d), h=loja.horario_funcionamento||{};
 if(!/^\d\d:\d\d$/.test(h.abertura||'')||!/^\d\d:\d\d$/.test(h.fechamento||'')||h.abertura>=h.fechamento){acao='invalido';motivo='horário de funcionamento inválido';}
 else if(t<h.abertura||t>=h.fechamento){motivo='evento fora do horário de funcionamento';}
 else if(controle.alertas.some(a=>a.evento_id===e.id)){acao='duplicado';motivo='evento já possui registro de envio ou reserva';}
 else if(!loja.destinatarios || !loja.destinatarios.telegram_chat_id){acao='configuracao';motivo='chat do Telegram não configurado';}
 else {acao='enviar';chatId=String(loja.destinatarios.telegram_chat_id);mensagem=`⚡ Energia que dá Lucro\n${loja.nome}: ${e.equipamento_id} registrou porta aberta por ${e.duracao_s} segundos. Verifique o equipamento para evitar desperdício.`;
 controle.alertas.push({id:e.id+'-telegram',evento_id:e.id,loja_id:e.loja_id,canal:'telegram',status:'reservado',registrado_em:agora,mensagem});motivo='reserva registrada antes do envio';}
}
controle.logs.push({data_hora:agora,evento_id:e.id||null,loja_id:e.loja_id||null,resultado:acao,motivo});
return [{json:{acao,evento_id:e.id||null,loja_id:e.loja_id||null,chatId,mensagem,controle},binary:{data:{data:Buffer.from(JSON.stringify(controle,null,2),'utf8').toString('base64'),mimeType:'application/json',fileName:'controle_alertas.json'}}}];

const planejado=$('Validar e reservar').first().json; const resposta=$input.first().json;
const controle=planejado.controle, agora=new Date().toISOString();
const registro=controle.alertas.find(x=>x.evento_id===planejado.evento_id && x.status==='reservado');
if(!registro) throw new Error('Reserva não encontrada; verificar auditoria');
const sucesso=!!(resposta.message_id || resposta.result?.message_id);
registro.status=sucesso?'enviado':'incerto'; registro.enviado_em=sucesso?agora:null;
controle.logs.push({data_hora:agora,evento_id:planejado.evento_id,loja_id:planejado.loja_id,resultado:registro.status,motivo:sucesso?'Envio confirmado pelo Telegram':'Envio sem confirmação; conferir antes de reenviar'});
return [{json:{resultado:registro.status,evento_id:registro.evento_id},binary:{data:{data:Buffer.from(JSON.stringify(controle,null,2),'utf8').toString('base64'),mimeType:'application/json',fileName:'controle_alertas.json'}}}];
